function Dialog({title,onClose,children,wide=false}:{title:string;onClose:()=>void;children:ReactNode;wide?:boolean}){
 const ref=useRef<HTMLDivElement>(null);
 useEffect(()=>{const previous=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.body.style.overflow=previous;};},[]);
 return <div className="t-dialog-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div ref={ref} className={`t-dialog ${wide?'wide':''}`} role="dialog" aria-modal="true" aria-label={title} onKeyDown={e=>{if(e.key==='Escape'){e.stopPropagation();onClose();}if(e.key==='Tab'){const list=Array.from(ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),select:not(:disabled),a[href]')||[]).filter(el=>el.offsetParent!==null);if(list.length&&e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1)?.focus();}else if(list.length&&!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus();}}}}><div className="t-dialog-head"><div><span className="t-eyebrow">知班 · 工作记录</span><h2>{title}</h2></div><IconButton title="关闭窗口" onClick={onClose}><X size={20}/></IconButton></div>{children}</div></div>;
}

function ImportPanel({state,today,onSave,notify}:{state:TeacherState;today:string;onSave:(items:WorkItem[])=>void;notify:(text:string)=>void}){
 const [text,setText]=useState(''),[base,setBase]=useState(today),[mode,setMode]=useState<'text'|'image'>('text'),[drafts,setDrafts]=useState<(ImportDraft&{selected:boolean})[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const imageRef=useRef<HTMLInputElement>(null);
 const duplicate=(d:ImportDraft)=>state.items.some(x=>x.title.trim()===d.title.trim()&&x.date===d.date&&x.time===d.time);
 function parse(){if(!text.trim()){setError('请先粘贴工作通知或上传图片识别。');return;}const found=parseWorkText(text,base);if(!found.length){setError('没有发现可整理的工作内容，请检查原文。');return;}setError('');setDrafts(found.map(d=>({...d,selected:!duplicate(d)})));}
 async function image(file:File){setBusy(true);setError('');try{const result=await readScheduleImage(file);setText(result);setDrafts([]);notify('已识别图片文字，请核对后整理为工作安排');}catch(e){setError(e instanceof Error?e.message:'图片识别失败，可粘贴文字继续。');}finally{setBusy(false);}}
 function accept(){const selected=drafts.filter(d=>d.selected);if(!selected.length){setError('请至少勾选一项工作。');return;}if(selected.some(d=>!d.title.trim()||!d.date)){setError('请为选中的每项工作填写标题与日期。');return;}const seen=new Set<string>();const items:WorkItem[]=[];for(const d of selected){const key=`${d.title.trim()}\n${d.date}\n${d.time}`;if(seen.has(key)||duplicate(d))continue;seen.add(key);items.push({id:teacherId(),title:d.title.trim(),date:d.date,time:d.time,priority:d.priority,category:d.category,status:'pending',remind:d.remind,remindBefore:d.category==='exam'?1440:30,notes:d.notes,createdAt:isoNow(),source:text.slice(0,1000)});}if(!items.length){setError('选中的事项已存在，未重复导入。');return;}onSave(items);}
 function update(index:number,values:Partial<ImportDraft&{selected:boolean}>){setDrafts(d=>d.map((x,i)=>i===index?{...x,...values}:x));}
 return <><div className="t-import-intro"><span className="t-big-icon green"><Sparkles size={22}/></span><div><strong>把工作通知，整理成清晰的安排。</strong><p>提取日期与事项，确认后同步到待办、周程和学期日历。</p></div></div><div className="t-tabs t-import-tabs"><button className={mode==='text'?'active':''} onClick={()=>setMode('text')}><FileText size={14}/>粘贴文字</button><button className={mode==='image'?'active':''} onClick={()=>setMode('image')}><ImagePlus size={14}/>图片周程</button></div>{mode==='image'&&<><input type="file" className="t-hidden" accept="image/*" ref={imageRef} onChange={e=>{const f=e.target.files?.[0];e.target.value='';if(f)void image(f);}}/><button className="t-image-upload" disabled={busy} onClick={()=>imageRef.current?.click()}>{busy?<LoaderCircle className="t-spin" size={26}/>:<ImagePlus size={26}/>}<strong>{busy?'正在识别图片文字…':'上传周程截图或拍照图片'}</strong><small>本机 Apple Vision 识别 · 图片不上传到第三方 · 最大 10 MB</small></button></>}<label className="t-field">{mode==='image'?'识别结果（可直接修改）':'工作通知原文'}<textarea value={text} onChange={e=>{setText(e.target.value);setDrafts([]);}} maxLength={20000} rows={6} placeholder={'例如：\n周三上午8:30召开班主任例会\n周四17:00前提交学生资助材料\n周五下午2点开展班级阅读活动'}/></label><div className="t-import-controls"><label>“本周 / 下周”的参考日期 <input type="date" value={base} required onChange={e=>setBase(e.target.value)}/></label><button className="t-btn primary" disabled={busy||!base} onClick={parse}><Sparkles size={15}/>整理为工作安排</button></div>{error&&<div className="t-form-error" role="alert"><AlertCircle size={15}/>{error}</div>}{drafts.length>0&&<div className="t-import-preview"><h3>识别到 {drafts.length} 项工作 <small>请核对日期、时间和提醒设置</small></h3>{drafts.map((d,i)=><div className={`t-draft ${!d.date?'needs-review':''}`} key={i}><div><input aria-label={`选择第${i+1}项`} type="checkbox" checked={d.selected} onChange={e=>update(i,{selected:e.target.checked})}/><input aria-label={`第${i+1}项标题`} value={d.title} onChange={e=>update(i,{title:e.target.value})}/>{duplicate(d)&&<span className="t-tag orange">已存在</span>}</div><div className="t-draft-fields"><label>日期<input type="date" value={d.date} onChange={e=>update(i,{date:e.target.value})}/></label><label>时间<input type="time" value={d.time} onChange={e=>update(i,{time:e.target.value})}/></label><label>优先级<select value={d.priority} onChange={e=>update(i,{priority:e.target.value as WorkItem['priority']})}>{Object.entries(priorityNames).map(([k,v])=><option value={k} key={k}>{v}</option>)}</select></label><label className="t-draft-reminder"><input type="checkbox" checked={d.remind} onChange={e=>update(i,{remind:e.target.checked})}/>提醒</label></div>{!d.date&&<small className="t-needs-review">原文未明确日期，请补充后导入。</small>}</div>)}<div className="t-dialog-footer"><span className="t-inline-note">重复事项自动跳过；导入后可撤销。</span><button className="t-btn primary" onClick={accept}><Check size={15}/>确认导入 {drafts.filter(x=>x.selected).length} 项</button></div></div>}<p className="t-inline-note">文字整理采用本机规则识别，模糊信息需人工核对。原文保存在对应事项的来源中。</p></>;
}
